    getHoursLeft() {
        const expireAt = this.time + TIME_LIMIT_SECONDS;
        const now = Math.floor(Date.now() / 1000);
        const diff = expireAt - now;

        if (diff < 0) {
            return 0;
        }

        return Math.floor(diff / 60 / 60);
    }

