const COMBAT_TRAINED_SKILLS = ['prayer'];
const GOAL_SKILLS = SKILLS.concat(COMBAT_TRAINED_SKILLS); // full pool for a skill goal

// dreams (long-term aspirations) live in dreams.js; goals.js delegates and reads
