// point a second npc's interlocutor at the player so it can speak
async function npcSpeak(player, npc, ...lines) {
    const previous = npc.interlocutor;
    npc.interlocutor = player;

    try {
        await npc.say(...lines);
    } finally {
        npc.interlocutor = previous;
    }
}

