function spawnNpc(world, id, x, y) {
    const npc = new NPC(world, {
        id,
        x,
        y,
        minX: x,
        maxX: x,
        minY: y,
        maxY: y
    });
    delete npc.respawn;
    world.addEntity('npcs', npc);
    return npc;
}

