const BLESSED_GOLDEN_BOWL_WITH_PLAIN_WATER_ID = 1286;
const GOLDEN_BOWL_WITH_PLAIN_WATER_ID = 1287;

const PIE_DISH_ID = 251;
const BOWL_ID = 341;
const BLESSED_GOLDEN_BOWL_ID = 1266;
const GOLDEN_BOWL_ID = 1188;

