// plugin entry points

async function onTalkToNPC(player, npc) {
    if (!questsEnabled(player)) {
        return false;
    }

    const questState = stage(player);

    if (npc.id === KRESH_ID) {
        player.engage(npc);
        await kreshDialogue(player, npc);
        player.disengage();
        return true;
    }

    if (npc.id === HEAD_WIZARD_ID) {
        // head wizard is shared with rune mysteries (a separate plugin
        // registered after this). peeling intercepts only when it has lines:
        // the quest is in progress (stages 2..11), the post-kresh reward is
        // pending, or the quest can start (stage 0/1 once rune mysteries is done).
        const runeMysteriesDone = player.questStages.runeMysteries === -1;
        const peelingStartable =
            runeMysteriesDone &&
            (questState === STATE_NOT_BEGUN ||
                questState === STATE_STARTED_QUEST_WITH_KRESH);
        const peelingHasLines =
            peelingStartable ||
            (questState >= STATE_STARTED_QUEST_WITH_SEDRIDOR &&
                questState <= STATE_KRESH_NEEDS_RECIPES) ||
            (questState === STATE_COMPLETE &&
                player.cache.sedridor_post_kresh_quest_dialogue);

        if (peelingHasLines) {
            player.engage(npc);
            await sedridorDialogue(player, npc);
            player.disengage();
            return true;
        }
        return false;
    }

    if (npc.id === MAKE_OVER_MAGE_ID) {
        // quest-active states 5..11 override the mage, else fall through
        if (
            questState >= STATE_SEDRIDOR_SUGGESTED_YOU_VISIT_MAKE_OVER_MAGE &&
            questState <= STATE_KRESH_NEEDS_RECIPES
        ) {
            player.engage(npc);
            await makeOverMageDialogue(player, npc);
            player.disengage();
            return true;
        }
        return false;
    }

    if (npc.id === AGGIE_ID) {
        // quest-active states 8..11 override Aggie, else fall through
        if (
            questState >= STATE_A_NEW_OGRE &&
            questState <= STATE_KRESH_NEEDS_RECIPES
        ) {
            player.engage(npc);
            await aggieDialogue(player, npc);
            player.disengage();
            return true;
        }
        return false;
    }

    return false;
}

